  // Calcular el costo total directo actual de la billetera
  const totalCostosDirectos = costos.reduce((acc, c) => acc + parseFloat(c.monto_total), 0);
  const presupuestoEstimado = parseFloat(cicloData.presupuesto_estimado) || 0;
