              <form onSubmit={handleCreateFinca} className="p-6 space-y-4 text-gray-800 bg-[#FAFDFB]">
                <div>
                  <label className="block text-2xs font-extrabold text-gray-500 uppercase tracking-wider mb-1">Nombre de la Finca</label>
                  <input 
