                  <label className="block text-2xs font-extrabold text-gray-500 uppercase tracking-wider mb-1">Área Total (Hectáreas)</label>
                  <input 
                    type="number" step="0.01" min="0.1" required
                    value={editingFinca.area_total_ha}
                    onChange={(e) => setEditingFinca({...editingFinca, area_total_ha: e.target.value})}
                    className="w-full px-4 py-3 bg-white border border-emerald-100 rounded-xl focus:ring-1 focus:ring-emerald-500 outline-none transition-all font-semibold text-gray-900"
                  />
                </div>

                {rol === 'ADMIN' && (
                  <div>
                    <label className="block text-2xs font-extrabold text-gray-500 uppercase tracking-wider mb-1">
                      Asignar al Productor Propietario <span className="text-red-500">*</span>
                    </label>
                    <select
                      required
                      value={editingFinca.productor_id}
                      onChange={(e) => setEditingFinca({...editingFinca, productor_id: e.target.value})}
                      className="w-full px-4 py-3 bg-white border border-emerald-100 rounded-xl focus:ring-1 focus:ring-emerald-500 outline-none transition-all font-semibold text-gray-900 cursor-pointer"
                    >
                      <option value="" disabled>Seleccione un Productor</option>
                      {productores.map(prod => (
                        <option key={prod.id} value={prod.id}>
                          {prod.first_name} {prod.last_name} ({prod.email})
                        </option>
                      ))}
                    </select>
                  </div>
                )}

                <div className="mt-8 flex gap-3 pt-4 border-t border-emerald-50">
                  <button 
                    type="button" 
                    onClick={() => setIsEditModalOpen(false)}
                    className="flex-1 px-4 py-3 text-gray-600 font-bold bg-white border border-gray-250 border-gray-200 hover:bg-gray-50 rounded-xl transition-all"
                  >
                    Cancelar
                  </button>
                  <button 
                    type="submit" 
                    disabled={saving}
                    className="flex-1 px-4 py-3 text-white font-bold bg-gradient-to-r from-[#1E5631] to-[#4C9A2A] hover:opacity-95 rounded-xl shadow-md transition-all flex justify-center items-center gap-2"
                  >
                    {saving ? <><Loader className="w-5 h-5 animate-spin" /> Guardando</> : 'Guardar Cambios'}
                  </button>
                </div>
              </form>
            </motion.div>
          </div>
        )}
      </AnimatePresence>
    </div>
  );
}

import { useState, useEffect } from 'react';
import { motion } from 'framer-motion';
import { 
  Tractor, LogOut, Loader, ArrowLeft, Calendar, 
  TrendingUp, Maximize, BarChart2, X, 
  Sparkles, Award, MapPin, Activity, AlertTriangle, ListFilter
} from 'lucide-react';
import { useNavigate, useLocation } from 'react-router-dom';
import axios from 'axios';
import { API_BASE_URL } from '../api';

export default function HistorialProduccion() {
  const navigate = useNavigate();
  const location = useLocation();

  // Estados de datos
  const [harvests, setHarvests] = useState([]);
  const [fincas, setFincas] = useState([]);
  const [lotes, setLotes] = useState([]);
  const [filteredLotes, setFilteredLotes] = useState([]);
  
  // Estados de control
  const [loading, setLoading] = useState(true);
  
  // Filtros seleccionados
  const [selectedFinca, setSelectedFinca] = useState('');
  const [selectedLote, setSelectedLote] = useState('');

  // Datos del usuario logueado
  const username = localStorage.getItem('username');
  const rol = localStorage.getItem('rol');
  const token = localStorage.getItem('token');

  const fetchInitialData = async (preFincaId, preLoteId) => {
    try {
      setLoading(true);
      setError('');

      // 1. Obtener Fincas
      const fincasRes = await axios.get(`${API_BASE_URL}/api/fincas/`, {
        headers: { Authorization: `Bearer ${token}` }
      });
      setFincas(fincasRes.data);

      // 2. Obtener Lotes
      const lotesRes = await axios.get(`${API_BASE_URL}/api/lotes/`, {
        headers: { Authorization: `Bearer ${token}` }
      });
      setLotes(lotesRes.data);

      // Si se pre-filtró una finca, limitar los lotes disponibles en el selector
      if (preFincaId) {
        const filtered = lotesRes.data.filter(l => l.finca === parseInt(preFincaId));
        setFilteredLotes(filtered);
      } else {
        setFilteredLotes(lotesRes.data);
      }

      // 3. Obtener Cosechas (con filtros si aplican)
      let url = `${API_BASE_URL}/api/cosechas/`;
      const params = [];
      if (preLoteId) {
        params.push(`lote_id=${preLoteId}`);
      } else if (preFincaId) {
        params.push(`finca_id=${preFincaId}`);
      }
      
      if (params.length > 0) {
        url += `?${params.join('&')}`;
      }

      const cosechasRes = await axios.get(url, {
        headers: { Authorization: `Bearer ${token}` }
      });
      setHarvests(cosechasRes.data);

    } catch (err) {
      console.error(err);
      setError('No se pudieron cargar los datos del historial de rendimiento.');
    } finally {
      setLoading(false);
    }
  };

  // Inicialización y carga de filtros y datos
  useEffect(() => {
    if (!token) {
      navigate('/login');
      return;
    }

    // Si viene algún pre-filtro por navegación
    const stateFincaId = location.state?.fincaId || '';
    const stateLoteId = location.state?.loteId || '';

    if (stateFincaId) setSelectedFinca(stateFincaId.toString());
    if (stateLoteId) setSelectedLote(stateLoteId.toString());

    fetchInitialData(stateFincaId, stateLoteId);
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [token]);

  // Cargar cosechas filtradas cuando cambie Finca o Lote
  const fetchFilteredHarvests = async (fincaId, loteId) => {
    try {
      setLoading(true);
      setError('');
      
      let url = `${API_BASE_URL}/api/cosechas/`;
      const queryParams = {};
      if (loteId) {
        queryParams.lote_id = loteId;
      } else if (fincaId) {
        queryParams.finca_id = fincaId;
      }

      const response = await axios.get(url, {
        headers: { Authorization: `Bearer ${token}` },
        params: queryParams
      });
      setHarvests(response.data);
    } catch (err) {
      console.error(err);
      setError('Error al recargar el listado de cosechas con los filtros aplicados.');
    } finally {
      setLoading(false);
    }
  };

  // Manejar cambio en el selector de Fincas
  const handleFincaChange = (e) => {
    const fincaId = e.target.value;
    setSelectedFinca(fincaId);
    setSelectedLote(''); // Limpiar lote al cambiar de finca

    if (fincaId) {
      // Filtrar lotes de esta finca
      const filtered = lotes.filter(l => l.finca === parseInt(fincaId));
      setFilteredLotes(filtered);
      fetchFilteredHarvests(fincaId, '');
    } else {
      setFilteredLotes(lotes);
      fetchFilteredHarvests('', '');
    }
  };

  // Manejar cambio en el selector de Lotes
  const handleLoteChange = (e) => {
    const loteId = e.target.value;
    setSelectedLote(loteId);
    fetchFilteredHarvests(selectedFinca, loteId);
  };

  // Restablecer todos los filtros
  const handleClearFilters = () => {
    setSelectedFinca('');
    setSelectedLote('');
    setFilteredLotes(lotes);
    fetchFilteredHarvests('', '');
  };

  const handleLogout = () => {
    localStorage.clear();
    navigate('/login');
  };

  // --- CÁLCULO DE KPIs DINÁMICOS (WOW ANALYTICS) ---
  const totalHarvestsCount = harvests.length;

  const totalProductionKg = harvests.reduce((sum, h) => sum + parseFloat(h.produccion_obtenida_kg || 0), 0);

  const averageYield = totalHarvestsCount > 0 
    ? (harvests.reduce((sum, h) => sum + parseFloat(h.rendimiento_ton_ha || 0), 0) / totalHarvestsCount).toFixed(2)
    : '0.00';

  // Buscar el récord (mejor rendimiento)
  const bestHarvest = harvests.reduce((max, h) => {
    const currentYield = parseFloat(h.rendimiento_ton_ha || 0);
    const maxYield = parseFloat(max?.rendimiento_ton_ha || 0);
    return currentYield > maxYield ? h : max;
  }, null);

  // Formateador de números
  const formatKg = (kg) => {
    return new Intl.NumberFormat('es-CO').format(kg);
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-[#E2F0E6] via-[#FAFDFB] to-[#D5EDDB] text-gray-800 font-sans selection:bg-emerald-600 selection:text-white relative pb-20 overflow-hidden">
      
      {/* Orbes decorativos */}
      <div className="absolute top-20 left-10 w-96 h-96 bg-[#4C9A2A]/10 rounded-full blur-3xl pointer-events-none"></div>
      <div className="absolute bottom-20 right-20 w-96 h-96 bg-[#1E5631]/10 rounded-full blur-3xl pointer-events-none"></div>

      {/* Navbar con efecto de cristal */}
      <nav className="sticky top-0 z-40 backdrop-blur-md bg-[#FAFDFB]/90 border-b border-emerald-100/90 shadow-sm transition-all duration-300">
        <div className="max-w-7xl mx-auto px-6 h-20 flex items-center justify-between">
          <div className="flex items-center gap-3 cursor-pointer" onClick={() => navigate('/')}>
            <div className="w-10 h-10 bg-gradient-to-tr from-[#1E5631] to-[#4C9A2A] rounded-xl flex items-center justify-center shadow-md">
              <Tractor className="w-5 h-5 text-white" />
            </div>
            <span className="text-xl font-black tracking-tight text-[#0D1A12] flex items-center gap-1.5">
              SIG-ARROZ
              <span className="text-xs font-bold text-[#D4AF37] px-2 py-0.5 rounded-md bg-[#D4AF37]/15 border border-[#D4AF37]/35 shadow-sm">
                Rendimientos
              </span>
            </span>
          </div>

          <div className="flex items-center gap-4">
            <div className="text-right hidden sm:block">
              <p className="text-sm font-black text-gray-900">{username || 'Productor'}</p>
              <p className="text-2xs font-extrabold text-[#D4AF37] uppercase tracking-wider bg-[#1E5631] px-2 py-0.5 rounded shadow-sm">{rol}</p>
            </div>
            <button 
              onClick={handleLogout}
              className="p-2.5 text-gray-600 hover:text-red-650 hover:bg-red-50 rounded-xl transition-all border border-gray-150 hover:border-red-200 shadow-sm bg-white"
              title="Cerrar Sesión"
            >
              <LogOut className="w-5 h-5" />
            </button>
          </div>
        </div>
      </nav>

      {/* Contenedor principal */}
      <main className="max-w-7xl mx-auto px-6 py-8 space-y-8 relative z-10">
        
        {/* Botón de regreso */}
        <button 
          onClick={() => navigate(-1)}
          className="flex items-center gap-2 text-gray-600 hover:text-emerald-700 font-bold transition-colors group"
        >
          <ArrowLeft className="w-5 h-5 transition-transform group-hover:-translate-x-1" />
          Volver atrás
        </button>

        {/* Banner principal */}
        <motion.div 
          initial={{ opacity: 0, y: -10 }}
          animate={{ opacity: 1, y: 0 }}
          className="bg-gradient-to-r from-[#1E5631] via-[#2A6C40] to-[#4C9A2A] text-white border-b-4 border-[#D4AF37] rounded-3xl p-8 shadow-xl relative overflow-hidden"
        >
          <div className="absolute inset-0 bg-[radial-gradient(circle_at_30%_30%,rgba(255,255,255,0.08),transparent)] pointer-events-none"></div>
          
          <div className="relative z-10 space-y-4 max-w-3xl">
            <span className="text-2xs font-black text-[#D4AF37] uppercase tracking-widest bg-white/10 border border-white/20 px-3 py-1 rounded-full">
              📊 Historial y Analítica Agronómica
            </span>
            <h1 className="text-3xl sm:text-4xl font-black tracking-tight leading-none mt-2 drop-shadow-md">
              Rendimiento y Productividad de Cultivos
            </h1>
            <p className="text-sm sm:text-base text-emerald-50 font-semibold leading-relaxed drop-shadow-sm">
              Consulta el historial completo de cosechas de tus fincas. Evalúa los rendimientos calculados automáticamente por hectárea, detecta tendencias de calidad según humedad o impurezas y haz un seguimiento a tus records de producción.
            </p>
          </div>
        </motion.div>

        {/* Tarjetas de KPIs */}
        <div className="grid grid-cols-1 md:grid-cols-4 gap-6">
          
          {/* Promedio de Rendimiento */}
          <div className="bg-white border-l-4 border-emerald-600 border border-emerald-100 rounded-2xl p-6 shadow-md hover:shadow-lg transition-all">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-2xs text-gray-500 font-bold uppercase tracking-wider">Rendimiento Promedio</p>
                <p className="text-3xl font-black text-gray-900 mt-2">
                  {averageYield} <span className="text-xs font-bold text-emerald-600">Ton/Ha</span>
                </p>
              </div>
              <div className="w-12 h-12 rounded-xl bg-emerald-50 border border-emerald-100 flex items-center justify-center text-emerald-700 shadow-sm">
                <TrendingUp className="w-6 h-6 animate-pulse" />
              </div>
            </div>
            <div className="mt-3 text-3xs text-gray-400 font-bold uppercase tracking-wider flex items-center gap-1">
              <Activity className="w-3.5 h-3.5 text-emerald-500" />
              Productividad media registrada
            </div>
          </div>

          {/* Récord Histórico */}
          <div className="bg-white border-l-4 border-[#D4AF37] border border-amber-100 rounded-2xl p-6 shadow-md hover:shadow-lg transition-all relative overflow-hidden">
            {bestHarvest && (
              <div className="absolute top-0 right-0 w-16 h-16 bg-[#D4AF37]/5 rounded-bl-full pointer-events-none"></div>
            )}
            <div className="flex items-center justify-between">
              <div>
                <p className="text-2xs text-gray-500 font-bold uppercase tracking-wider">Récord de Rendimiento</p>
                <p className="text-3xl font-black text-gray-900 mt-2">
                  {bestHarvest ? bestHarvest.rendimiento_ton_ha : '0.00'}{' '}
                  <span className="text-xs font-bold text-[#b8952b]">Ton/Ha</span>
                </p>
              </div>
              <div className="w-12 h-12 rounded-xl bg-amber-50 border border-amber-100 flex items-center justify-center text-[#b8952b] shadow-sm">
                <Award className="w-6 h-6 text-[#D4AF37]" />
              </div>
            </div>
            <div className="mt-3 text-3xs text-gray-550 text-gray-500 font-bold truncate max-w-full">
              {bestHarvest ? (
                <span className="text-amber-800 bg-amber-50 px-2 py-0.5 rounded shadow-sm border border-amber-200/50">
                  🏆 Lote: {bestHarvest.lote_nombre}
                </span>
              ) : (
                'Sin registros aún'
              )}
            </div>
          </div>

          {/* Producción Total */}
          <div className="bg-white border-l-4 border-blue-600 border border-blue-100 rounded-2xl p-6 shadow-md hover:shadow-lg transition-all">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-2xs text-gray-500 font-bold uppercase tracking-wider">Producción Acumulada</p>
                <p className="text-3xl font-black text-gray-900 mt-2">
                  {formatKg(totalProductionKg)} <span className="text-xs font-bold text-blue-600">Kg</span>
                </p>
              </div>
              <div className="w-12 h-12 rounded-xl bg-blue-50 border border-blue-100 flex items-center justify-center text-blue-700 shadow-sm">
                <Maximize className="w-6 h-6" />
              </div>
            </div>
            <div className="mt-3 text-3xs text-gray-400 font-bold uppercase tracking-wider flex items-center gap-1">
              <Sparkles className="w-3.5 h-3.5 text-blue-500" />
              Volumen total cosechado
            </div>
          </div>

          {/* Ciclos Concluidos */}
          <div className="bg-white border-l-4 border-purple-600 border border-purple-100 rounded-2xl p-6 shadow-md hover:shadow-lg transition-all">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-2xs text-gray-500 font-bold uppercase tracking-wider">Ciclos Cosechados</p>
                <p className="text-3xl font-black text-gray-900 mt-2">
                  {totalHarvestsCount} <span className="text-xs font-bold text-purple-600">Ciclos</span>
                </p>
              </div>
              <div className="w-12 h-12 rounded-xl bg-purple-50 border border-purple-100 flex items-center justify-center text-purple-700 shadow-sm">
                <BarChart2 className="w-6 h-6" />
              </div>
            </div>
            <div className="mt-3 text-3xs text-gray-400 font-bold uppercase tracking-wider flex items-center gap-1">
              <Calendar className="w-3.5 h-3.5 text-purple-500" />
              Cierres productivos registrados
            </div>
          </div>

        </div>

        {/* Panel de Filtros */}
        <section className="bg-white/80 backdrop-blur-md border border-emerald-100 rounded-3xl p-6 shadow-md space-y-6">
          <div className="flex items-center justify-between pb-4 border-b border-emerald-100">
            <div className="flex items-center gap-2">
              <ListFilter className="w-5 h-5 text-emerald-700" />
              <div>
                <h3 className="text-base font-black text-gray-900">Búsqueda y Filtros de Cosechas</h3>
                <p className="text-2xs text-gray-500 font-bold">Filtra el historial por finca y lote para evaluar rendimientos específicos</p>
              </div>
            </div>
            
            {(selectedFinca || selectedLote) && (
              <button 
                onClick={handleClearFilters}
                className="text-2xs font-extrabold text-red-650 hover:underline flex items-center gap-1 bg-red-50 border border-red-200/50 px-2.5 py-1 rounded-lg transition-all text-red-600"
              >
                <X className="w-3.5 h-3.5" />
                Limpiar Filtros
              </button>
            )}
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            
            {/* Selector de Finca */}
            <div className="flex flex-col gap-2">
              <label className="text-xs font-bold text-gray-500 uppercase tracking-wider">Finca:</label>
              <select
                value={selectedFinca}
                onChange={handleFincaChange}
                className="w-full px-4 py-3 bg-[#FAFDFB] border border-emerald-100 rounded-xl text-xs font-bold text-gray-700 focus:outline-none focus:border-emerald-500 cursor-pointer"
              >
                <option value="">Todas las Fincas</option>
                {fincas.map(f => (
                  <option key={f.id} value={f.id}>{f.nombre}</option>
                ))}
              </select>
            </div>

            {/* Selector de Lote */}
            <div className="flex flex-col gap-2">
              <label className="text-xs font-bold text-gray-500 uppercase tracking-wider">Lote:</label>
              <select
                value={selectedLote}
                onChange={handleLoteChange}
                disabled={filteredLotes.length === 0}
                className="w-full px-4 py-3 bg-[#FAFDFB] border border-emerald-100 rounded-xl text-xs font-bold text-gray-700 focus:outline-none focus:border-emerald-500 cursor-pointer disabled:opacity-50"
              >
                <option value="">Todos los Lotes</option>
                {filteredLotes.map(l => (
                  <option key={l.id} value={l.id}>{l.nombre}</option>
                ))}
              </select>
            </div>

          </div>
        </section>

        {/* Tabla / Contenido de Cosechas */}
        <section className="bg-white border border-emerald-100 rounded-3xl shadow-md overflow-hidden">
          
          <div className="px-6 py-5 border-b border-emerald-50 bg-[#FAFDFB] flex items-center justify-between">
            <h3 className="text-lg font-black text-gray-900">Historial Detallado</h3>
            <span className="text-xs font-bold text-emerald-800 bg-emerald-50 px-3 py-1 rounded-full">
              {totalHarvestsCount} Registro(s) de producción
            </span>
          </div>

          {loading ? (
            <div className="flex flex-col items-center justify-center py-20">
              <Loader className="w-10 h-10 text-emerald-700 animate-spin mb-4" />
              <p className="text-sm text-gray-500 font-bold">Filtrando historial de cosechas...</p>
            </div>
          ) : harvests.length === 0 ? (
            /* Empty State */
            <div className="p-12 text-center">
              <div className="w-20 h-20 bg-gray-50 rounded-full flex items-center justify-center mx-auto mb-4 border border-gray-150">
                <Calendar className="w-10 h-10 text-gray-400" />
              </div>
              <h4 className="text-base font-black text-gray-900 mb-1">No hay registros de cosecha</h4>
              <p className="text-xs text-gray-500 max-w-sm mx-auto mb-6">
                No se encontraron cosechas que coincidan con los filtros seleccionados o el productor aún no registra cierres.
              </p>
              <button 
                onClick={() => navigate('/')}
                className="text-emerald-700 font-bold hover:underline"
              >
                Ir a Fincas para gestionar un lote
              </button>
            </div>
          ) : (
            /* Tabla Interactiva Premium */
            <div className="overflow-x-auto">
              <table className="w-full text-left border-collapse">
                <thead>
                  <tr className="bg-gray-50 border-b border-gray-100 text-3xs font-extrabold uppercase text-gray-400 tracking-wider">
                    <th className="px-6 py-4">Finca / Lote</th>
                    <th className="px-6 py-4">Ciclo de Cultivo</th>
                    <th className="px-6 py-4">Fecha Cosecha</th>
                    <th className="px-6 py-4">Producción (Kg)</th>
                    <th className="px-6 py-4 text-center">Humedad (%)</th>
                    <th className="px-6 py-4 text-center">Impurezas (%)</th>
                    <th className="px-6 py-4 text-right">Rendimiento</th>
                    <th className="px-6 py-4 text-center">Estado Liquidación</th>
                    <th className="px-6 py-4 pl-8 max-w-xs">Condiciones / Observaciones</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-gray-100 text-xs font-semibold text-gray-700">
                  {harvests.map((harvest) => {
                    const yieldValue = parseFloat(harvest.rendimiento_ton_ha || 0);
                    const moisture = parseFloat(harvest.humedad_grano_porcentaje || 0);
                    const impurities = parseFloat(harvest.impurezas_porcentaje || 0);

                    // Determinar colores de rendimiento
                    let yieldStyle = "text-gray-900 font-black";
                    let yieldBadge = null;

                    if (yieldValue >= 6.0) {
                      yieldStyle = "text-emerald-700 font-black text-sm";
                      yieldBadge = (
                        <span className="text-[10px] font-bold text-emerald-800 bg-emerald-50 px-2 py-0.5 rounded shadow-sm border border-emerald-250 ml-1">
                          Óptimo
                        </span>
                      );
                    } else if (yieldValue < 4.0) {
                      yieldStyle = "text-amber-700 font-black";
                      yieldBadge = (
                        <span className="text-[10px] font-bold text-amber-800 bg-amber-50 px-2 py-0.5 rounded shadow-sm border border-amber-250 ml-1 inline-flex items-center gap-0.5" title="Rendimiento por debajo de la media regional (4 Ton/Ha)">
                          <AlertTriangle className="w-3 h-3" /> Bajo
                        </span>
                      );
                    }

                    // Determinar calidad de humedad (ideal entre 18% y 22% al cosechar)
                    let moistureStyle = "bg-gray-100 text-gray-800";
                    if (moisture >= 18 && moisture <= 22) {
                      moistureStyle = "bg-emerald-50 text-emerald-700 border border-emerald-200/50";
                    } else if (moisture > 22) {
                      moistureStyle = "bg-amber-50 text-amber-700 border border-amber-200/50";
                    } else if (moisture > 0 && moisture < 18) {
                      moistureStyle = "bg-blue-50 text-blue-700 border border-blue-200/50";
                    }

                    // Determinar impurezas (ideal < 5%)
                    let impuritiesStyle = "bg-gray-100 text-gray-800";
                    if (impurities > 5.0) {
                      impuritiesStyle = "bg-red-50 text-red-700 border border-red-200/50";
                    } else if (impurities > 0) {
                      impuritiesStyle = "bg-emerald-50 text-emerald-700 border border-emerald-200/50";
                    }

                    return (
                      <motion.tr 
                        key={harvest.id}
                        whileHover={{ backgroundColor: '#F8FAF9' }}
                        className="transition-colors"
                      >
                        <td className="px-6 py-4">
                          <div className="flex flex-col">
                            <span className="font-extrabold text-gray-900 flex items-center gap-1">
                              <MapPin className="w-3.5 h-3.5 text-emerald-600 shrink-0" />
                              {harvest.finca_nombre}
                            </span>
                            <span className="text-3xs text-gray-400 font-extrabold uppercase mt-0.5">
                              Lote: {harvest.lote_nombre} ({harvest.lote_area} Ha)
                            </span>
                          </div>
                        </td>
                        <td className="px-6 py-4">
                          <div className="flex flex-col">
                            <span className="font-bold text-gray-850">
                              {harvest.ciclo_nombre}
                            </span>
                            <span className="text-[10px] text-gray-500 font-semibold mt-0.5">
                              Variedad: {harvest.variedad_arroz}
                            </span>
                          </div>
                        </td>
                        <td className="px-6 py-4 text-gray-500 font-bold">
                          {new Date(harvest.fecha).toLocaleDateString('es-ES', {
                            year: 'numeric', month: 'short', day: 'numeric'
                          })}
                        </td>
                        <td className="px-6 py-4 font-bold text-gray-800">
                          {formatKg(harvest.produccion_obtenida_kg)} <span className="text-[10px] text-gray-400 font-bold">Kg</span>
                        </td>
                        <td className="px-6 py-4 text-center">
                          <span className={`text-2xs font-extrabold px-2.5 py-0.5 rounded-full ${moistureStyle}`}>
                            {moisture}%
                          </span>
                        </td>
                        <td className="px-6 py-4 text-center">
                          <span className={`text-2xs font-extrabold px-2.5 py-0.5 rounded-full ${impuritiesStyle}`}>
                            {impurities}%
                          </span>
                        </td>
                        <td className="px-6 py-4 text-right">
                          <div className="flex items-center justify-end gap-1.5">
                            <span className={yieldStyle}>{yieldValue}</span>
                            <span className="text-[10px] text-gray-400 font-extrabold uppercase shrink-0">Ton/Ha</span>
                            {yieldBadge}
                          </div>
                        </td>
                        <td className="px-6 py-4 text-center">
                          {harvest.estado_ciclo === 'FINALIZADO' ? (
                            <span className="text-[10px] font-bold text-blue-800 bg-blue-50 px-2.5 py-1 rounded shadow-sm border border-blue-200">
                              Liquidada
                            </span>
                          ) : (
                            <span className="text-[10px] font-bold text-amber-800 bg-amber-50 px-2.5 py-1 rounded shadow-sm border border-amber-200">
                              Pendiente
                            </span>
                          )}
                        </td>
                        <td className="px-6 py-4 pl-8 max-w-xs text-2xs text-gray-500 font-medium italic break-words">
                          {harvest.condiciones_cosecha || <span className="text-gray-300 font-normal">Sin observaciones</span>}
                        </td>
                      </motion.tr>
                    );
                  })}
                </tbody>
              </table>
            </div>
          )}

        </section>

      </main>
    </div>
  );
}

import { useState, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { ArrowLeft, FlaskConical, CalendarClock, Plus, X, Loader, Tractor, LogOut, FileText, CheckCircle2, Info } from 'lucide-react';
import { useNavigate, useParams, useLocation } from 'react-router-dom';
import axios from 'axios';
import { API_BASE_URL } from '../api';

export default function LoteDetalle() {
  const { loteId } = useParams();
  const location = useLocation();
  const navigate = useNavigate();

  const loteData = location.state?.lote || { nombre: 'Cargando Lote...' };
  const fincaData = location.state?.finca || null;

  const [activeTab, setActiveTab] = useState('analisis'); // 'analisis' | 'ciclos'
  
  // Data states
  const [ciclos, setCiclos] = useState([]);
  const [analisisList, setAnalisisList] = useState([]);
  const [loading, setLoading] = useState(true);
  
  // Reglas Agronómicas Calculadas (Suelo Apto para Arroz)
  const ultimoAnalisis = analisisList && analisisList.length > 0 ? analisisList[0] : null;
  const tieneAnalisis = analisisList && analisisList.length > 0;
  const esSueloApto = ultimoAnalisis ? parseFloat(ultimoAnalisis.ph) >= 5.5 : false;

  // Modals
  const [isModalCicloOpen, setIsModalCicloOpen] = useState(false);
  const [isModalAnalisisOpen, setIsModalAnalisisOpen] = useState(false);
  const [saving, setSaving] = useState(false);

  // Forms
  const [nuevoCiclo, setNuevoCiclo] = useState({
    nombre_ciclo: '',
    anio: new Date().getFullYear(),
    semestre: '1',
    variedad_arroz: '',
    presupuesto_estimado: '',
    estado: 'PLANIFICADO',
    fecha_inicio_real: new Date().toISOString().split('T')[0]
  });

  const [nuevoAnalisis, setNuevoAnalisis] = useState({
    fecha_muestreo: new Date().toISOString().split('T')[0],
    ph: '',
    materia_organica_porcentaje: '',
    fosforo_ppm: '',
    potasio_meq: '',
    textura: 'FRANCO',
    laboratorio: ''
  });

  const username = localStorage.getItem('username');
  const rol = localStorage.getItem('rol');
  const token = localStorage.getItem('token');

  const fetchData = async () => {
    setLoading(true);
    try {
      const [resCiclos, resAnalisis] = await Promise.all([
        axios.get(`${API_BASE_URL}/api/ciclos/?lote_id=${loteId}`, { headers: { Authorization: `Bearer ${token}` } }),
        axios.get(`${API_BASE_URL}/api/analisis-suelos/?lote_id=${loteId}`, { headers: { Authorization: `Bearer ${token}` } })
      ]);
      setCiclos(resCiclos.data);
      setAnalisisList(resAnalisis.data);
    } catch (err) {
      console.error(err);
      alert('Error al cargar la información del lote.');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    if (!token) {
      navigate('/login');
      return;
    }
    fetchData();
  }, [loteId, token]);

  const handleLogout = () => {
    localStorage.clear();
    navigate('/login');
  };

  const handleCreateCiclo = async (e) => {
    e.preventDefault();
    setSaving(true);
    try {
      const response = await axios.post(`${API_BASE_URL}/api/ciclos/`, {
        ...nuevoCiclo,
        lote: parseInt(loteId),
        presupuesto_estimado: parseFloat(nuevoCiclo.presupuesto_estimado)
      }, { headers: { Authorization: `Bearer ${token}` } });
      setCiclos([response.data, ...ciclos]);
      setIsModalCicloOpen(false);
      setNuevoCiclo({ nombre_ciclo: '', anio: new Date().getFullYear(), semestre: '1', variedad_arroz: '', presupuesto_estimado: '', estado: 'PLANIFICADO', fecha_inicio_real: new Date().toISOString().split('T')[0] });
    } catch (err) {
      console.error(err);
      alert(err.response?.data?.detail || 'Error al crear ciclo productivo.');
    } finally {
      setSaving(false);
    }
  };

  const handleCreateAnalisis = async (e) => {
    e.preventDefault();
    setSaving(true);
    try {
      const response = await axios.post(`${API_BASE_URL}/api/analisis-suelos/`, {
        ...nuevoAnalisis,
        lote: parseInt(loteId),
        ph: parseFloat(nuevoAnalisis.ph),
        materia_organica_porcentaje: parseFloat(nuevoAnalisis.materia_organica_porcentaje),
        fosforo_ppm: parseFloat(nuevoAnalisis.fosforo_ppm),
        potasio_meq: parseFloat(nuevoAnalisis.potasio_meq)
      }, { headers: { Authorization: `Bearer ${token}` } });
      setAnalisisList([response.data, ...analisisList]);
      setIsModalAnalisisOpen(false);
      setNuevoAnalisis({
        fecha_muestreo: new Date().toISOString().split('T')[0],
        ph: '', materia_organica_porcentaje: '', fosforo_ppm: '', potasio_meq: '',
        textura: 'FRANCO', laboratorio: ''
      });
    } catch (err) {
      console.error(err);
      const errorMsg = err.response?.data ? JSON.stringify(err.response.data) : 'Error al registrar el análisis de suelo.';
      alert(errorMsg);
    } finally {
      setSaving(false);
    }
  };

  const formatCurrency = (value) => {
    return new Intl.NumberFormat('es-CO', { style: 'currency', currency: 'COP' }).format(value);
  };

  const getPhBadge = (interpretacion) => {
    if (interpretacion.includes('Neutro')) return 'bg-emerald-100 text-emerald-800 border-emerald-200';
    if (interpretacion.includes('Ácido')) return 'bg-red-100 text-red-800 border-red-200';
    return 'bg-blue-100 text-blue-800 border-blue-200';
  };

  const getEstadoBadge = (estado) => {
    const estilos = {
      'PLANIFICADO': 'bg-amber-50 text-amber-700 border-amber-200',
      'EJECUCION': 'bg-blue-50 text-blue-700 border-blue-200',
      'COSECHADO': 'bg-emerald-50 text-emerald-700 border-emerald-200',
      'FINALIZADO': 'bg-gray-100 text-gray-700 border-gray-300'
    };
    return estilos[estado] || 'bg-gray-50 text-gray-600';
  };

  return (
    <div className="min-h-screen bg-gray-50">
      {/* Top Navbar */}
      <nav className="bg-white border-b border-gray-200 sticky top-0 z-40 shadow-sm">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="flex justify-between items-center h-16">
            <div className="flex items-center gap-2 cursor-pointer" onClick={() => navigate('/')}>
              <div className="w-10 h-10 bg-rice-green rounded-xl flex items-center justify-center shadow-md">
                <Tractor className="w-6 h-6 text-white" />
              </div>
              <span className="text-xl font-bold text-rice-dark tracking-tight">SIG-ARROZ</span>
            </div>
            
            <div className="flex items-center gap-4">
              <div className="text-right hidden sm:block">
                <p className="text-sm font-bold text-rice-dark">{username}</p>
                <p className="text-xs font-semibold text-rice-emerald uppercase tracking-wider">{rol}</p>
              </div>
              <button onClick={handleLogout} className="p-2 text-gray-500 hover:text-red-600 hover:bg-red-50 rounded-xl transition-colors">
                <LogOut className="w-5 h-5" />
              </button>
            </div>
          </div>
        </div>
      </nav>

      {/* Main Content */}
      <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
        {/* Botón de regreso dinámico */}
        <button 
          onClick={() => fincaData ? navigate(`/fincas/${fincaData.id}/lotes`, { state: { finca: fincaData } }) : navigate('/')}
          className="flex items-center gap-2 text-gray-600 hover:text-rice-green font-bold mb-6 transition-colors group"
        >
          <ArrowLeft className="w-5 h-5 transition-transform group-hover:-translate-x-1" />
          Volver a Lotes {fincaData ? `de ${fincaData.nombre}` : ''}
        </button>

        <div className="bg-white border border-gray-200 rounded-3xl p-6 sm:p-8 shadow-sm mb-6 relative overflow-hidden">
          <div className="absolute top-0 right-0 w-40 h-40 bg-rice-emerald/5 rounded-bl-full -mr-4 -mt-4"></div>
          <div className="relative z-10">
            <span className="text-xs font-bold text-rice-emerald uppercase tracking-widest bg-rice-emerald/10 px-3 py-1 rounded-full">Gestión Interna de Parcela</span>
            <h1 className="text-3xl font-extrabold text-gray-900 mt-3 tracking-tight">{loteData.nombre}</h1>
            {fincaData && <p className="text-gray-500 font-medium mt-1">Perteneciente a la finca {fincaData.nombre}</p>}
          </div>
        </div>

        {/* Guía Rápida Visual */}
        <div className="bg-blue-50/50 border border-blue-100 rounded-2xl p-5 mb-8 flex gap-4 shadow-sm">
          <div className="text-blue-500 shrink-0 mt-0.5">
            <Info className="w-6 h-6" />
          </div>
          <div>
            <h4 className="font-bold text-blue-900 text-sm">Guía de Operación del Lote</h4>
            <ol className="list-decimal list-inside text-sm text-blue-800/80 mt-1.5 space-y-1 font-medium">
              <li><strong>Primer Paso:</strong> Dirígete a la pestaña <em>"Análisis de Suelos"</em> y registra el muestreo del laboratorio (Obligatorio).</li>
              <li><strong>Segundo Paso:</strong> Una vez diagnosticado el suelo, ve a <em>"Ciclos Productivos"</em> e inicia un nuevo ciclo de siembra.</li>
              <li><strong>Tercer Paso:</strong> A medida que el cultivo crezca, registra las tareas y el monitoreo diario en el ciclo activo.</li>
            </ol>
          </div>
        </div>

        {/* TABS NAVIGATION */}
        <div className="flex border-b border-gray-200 mb-8">
          <button 
            onClick={() => setActiveTab('analisis')}
            className={`flex items-center gap-2 px-6 py-4 font-bold text-sm transition-colors relative ${activeTab === 'analisis' ? 'text-rice-green' : 'text-gray-500 hover:text-gray-700'}`}
          >
            <FlaskConical className="w-5 h-5" /> Análisis de Suelos
            {activeTab === 'analisis' && (
              <motion.div layoutId="activeTab" className="absolute bottom-0 left-0 right-0 h-0.5 bg-rice-green" />
            )}
          </button>

          <button 
            onClick={() => setActiveTab('ciclos')}
            className={`flex items-center gap-2 px-6 py-4 font-bold text-sm transition-colors relative ${activeTab === 'ciclos' ? 'text-rice-green' : 'text-gray-500 hover:text-gray-700'}`}
          >
            <CalendarClock className="w-5 h-5" /> Ciclos Productivos
            {activeTab === 'ciclos' && (
              <motion.div layoutId="activeTab" className="absolute bottom-0 left-0 right-0 h-0.5 bg-rice-green" />
            )}
          </button>
        </div>

        {/* TAB 1: CICLOS PRODUCTIVOS */}
        {activeTab === 'ciclos' && (
          <motion.div initial={{ opacity: 0, x: -10 }} animate={{ opacity: 1, x: 0 }} exit={{ opacity: 0 }}>
            <div className="flex justify-between items-center mb-6">
              <div>
                <h2 className="text-xl font-bold text-gray-900">Historial de Siembras</h2>
                <p className="text-gray-500 text-sm">Gestiona las temporadas de siembra y cosecha de este lote</p>
              </div>
              
              {/* MAGIA DE ROLES (RBAC): Actualizado para permitir que el TECNICO inicie ciclos */}
              {(
                <motion.button
                  whileHover={(!tieneAnalisis || !esSueloApto) ? {} : { scale: 1.02 }} 
                  whileTap={(!tieneAnalisis || !esSueloApto) ? {} : { scale: 0.98 }}
                  onClick={() => {
                    if (!tieneAnalisis) {
                      alert("🛑 REGLA AGRONÓMICA: No puedes iniciar un Ciclo Productivo sin antes conocer el estado de la tierra. Por favor, registra primero un Análisis de Suelos en la otra pestaña.");
                      return;
                    }
                    if (!esSueloApto) {
                      alert(`🛑 REGLA AGRONÓMICA: El último análisis de suelo (${ultimoAnalisis.fecha_muestreo}) reporta un pH de ${Number(ultimoAnalisis.ph).toFixed(1)} (${ultimoAnalisis.interpretacion_ph}), lo cual es INADECUADO para el cultivo de arroz. Aplica cal de enmienda y registra un nuevo análisis corregido (pH >= 5.5) para desbloquear la siembra.`);
                      return;
                    }
                    setIsModalCicloOpen(true);
                  }}
                  className={`px-4 py-2 rounded-xl font-semibold transition-all flex items-center gap-2 text-sm shadow-md ${
                    (!tieneAnalisis || !esSueloApto) 
                      ? 'bg-gray-300 text-gray-500 cursor-not-allowed shadow-none' 
                      : 'bg-rice-green text-white shadow-rice-green/30 hover:bg-[#154224]'
                  }`}
                >
                  <Plus className="w-4 h-4" /> Iniciar Nuevo Ciclo
                </motion.button>
              )}
            </div>

            {tieneAnalisis && !esSueloApto && (
              <div className="bg-red-50 border border-red-200 text-red-800 rounded-2xl p-5 mb-6 flex gap-4 shadow-sm">
                <Info className="w-6 h-6 text-red-500 shrink-0 mt-0.5" />
                <div>
                  <h4 className="font-bold text-red-900 text-sm">Bloqueo de Calidad: Suelo Inadecuado</h4>
                  <p className="text-sm text-red-800/80 mt-1.5 leading-relaxed font-medium">
                    El último análisis de suelo ({ultimoAnalisis.fecha_muestreo}) reporta una acidez de <strong>pH {Number(ultimoAnalisis.ph).toFixed(1)} ({ultimoAnalisis.interpretacion_ph})</strong>, lo cual es inaceptable para cultivar arroz.
                  </p>
                  <p className="text-sm text-red-800 mt-2 font-bold flex items-center gap-1">
                    💡 Acción: Debes realizar una enmienda caliza al terreno y registrar un nuevo análisis verificado (pH ≥ 5.5) para desbloquear la siembra.
                  </p>
                </div>
              </div>
            )}

            {loading ? (
              <div className="flex justify-center py-10"><Loader className="animate-spin text-rice-green w-8 h-8" /></div>
            ) : ciclos.length === 0 ? (
              <div className="bg-white border border-dashed border-gray-300 rounded-2xl p-10 text-center">
                <CalendarClock className="w-12 h-12 text-gray-300 mx-auto mb-3" />
                <h3 className="text-gray-900 font-bold">Sin ciclos registrados</h3>
                <p className="text-gray-500 text-sm mt-1">Este lote no tiene siembras programadas actualmente.</p>
              </div>
            ) : (
              <div className="grid grid-cols-1 lg:grid-cols-2 gap-4">
                {ciclos.map(ciclo => (
                  <div key={ciclo.id} className="bg-white border border-gray-200 rounded-2xl p-5 shadow-sm hover:shadow-md transition-all">
                    <div className="flex justify-between items-start mb-3">
                      <span className={`text-xxs font-bold uppercase tracking-wider px-2.5 py-1 border rounded-full ${getEstadoBadge(ciclo.estado)}`}>
                        {ciclo.estado}
                      </span>
                      <span className="text-xs font-bold text-gray-400">{ciclo.anio} - {ciclo.semestre === '1' ? 'Semestre A' : 'Semestre B'}</span>
                    </div>
                    <h3 className="text-lg font-bold text-gray-900 mb-1">{ciclo.nombre_ciclo}</h3>
                    <p className="text-sm font-semibold text-gray-500 mb-2">Var: {ciclo.variedad_arroz}</p>
                    <p className="text-sm font-semibold text-gray-500 flex items-center gap-1.5 mb-4">
                      Presupuesto: <span className="text-rice-emerald">{formatCurrency(ciclo.presupuesto_estimado)}</span>
                    </p>
                    <div className="pt-3 border-t border-gray-100 flex gap-3 text-sm">
                      <button 
                        onClick={() => navigate(`/lotes/${loteId}/ciclos/${ciclo.id}/gestion`, { state: { lote: loteData, finca: fincaData, ciclo } })}
                        className="text-rice-green font-bold hover:underline flex items-center gap-1"
                      >
                        Ver Tareas →
                      </button>
                    </div>
                  </div>
                ))}
              </div>
            )}
          </motion.div>
        )}

        {/* TAB 2: ANÁLISIS DE SUELOS */}
        {activeTab === 'analisis' && (
          <motion.div initial={{ opacity: 0, x: 10 }} animate={{ opacity: 1, x: 0 }} exit={{ opacity: 0 }}>
            <div className="flex justify-between items-center mb-6">
              <div>
                <h2 className="text-xl font-bold text-gray-900">Laboratorio y Suelos</h2>
                <p className="text-gray-500 text-sm">Registra y monitorea el perfil químico del terreno</p>
              </div>
              
              {/* Aquí el TECNICO sí puede ver y usar el botón, todos pueden registrar análisis */}
              <motion.button
                whileHover={{ scale: 1.02 }} whileTap={{ scale: 0.98 }}
                onClick={() => setIsModalAnalisisOpen(true)}
                className="bg-blue-600 text-white px-4 py-2 rounded-xl font-semibold shadow-md shadow-blue-600/30 hover:bg-blue-700 transition-all flex items-center gap-2 text-sm"
              >
                <Plus className="w-4 h-4" /> Registrar Análisis
              </motion.button>
            </div>

            {tieneAnalisis && esSueloApto && (
              <div className="bg-emerald-50 border border-emerald-100 rounded-2xl p-5 mb-6 flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4 shadow-sm">
                <div className="flex gap-4">
                  <CheckCircle2 className="w-6 h-6 text-emerald-500 shrink-0 mt-0.5" />
                  <div>
                    <h4 className="font-bold text-emerald-900 text-sm">¡Terreno Apto para Cultivo!</h4>
                    <p className="text-sm text-emerald-800/80 mt-1 font-medium">
                      El último análisis reporta un pH de {Number(ultimoAnalisis.ph).toFixed(1)} ({ultimoAnalisis.interpretacion_ph}). Ya puedes planificar un ciclo productivo en este lote.
                    </p>
                  </div>
                </div>
                <button 
                  onClick={() => {
                    setActiveTab('ciclos');
                    setIsModalCicloOpen(true);
                  }}
                  className="bg-rice-green text-white px-4 py-2.5 rounded-xl text-sm font-bold shadow-md shadow-rice-green/20 hover:bg-[#154224] transition-colors shrink-0 flex items-center gap-1.5"
                >
                  Iniciar Ciclo Productivo →
                </button>
              </div>
            )}

            {loading ? (
              <div className="flex justify-center py-10"><Loader className="animate-spin text-rice-green w-8 h-8" /></div>
            ) : analisisList.length === 0 ? (
              <div className="bg-white border border-dashed border-gray-300 rounded-2xl p-10 text-center">
                <FlaskConical className="w-12 h-12 text-gray-300 mx-auto mb-3" />
                <h3 className="text-gray-900 font-bold">Sin análisis de suelo</h3>
                <p className="text-gray-500 text-sm mt-1">Añade muestreos químicos para conocer el estado del terreno.</p>
              </div>
            ) : (
              <div className="grid grid-cols-1 lg:grid-cols-2 gap-4">
                {analisisList.map(ana => (
                  <div key={ana.id} className="bg-white border border-gray-200 rounded-2xl p-5 shadow-sm hover:shadow-md transition-all">
                    <div className="flex justify-between items-center mb-4">
                      <div className="flex items-center gap-2">
                        <FileText className="w-5 h-5 text-gray-400" />
                        <span className="font-bold text-gray-900">{ana.fecha_muestreo}</span>
                      </div>
                      <span className={`text-xs font-bold px-2 py-1 border rounded-lg ${getPhBadge(ana.interpretacion_ph)}`}>
                        pH: {Number(ana.ph).toFixed(1)} - {ana.interpretacion_ph}
                      </span>
                    </div>
                    
                    <div className="grid grid-cols-2 gap-2 text-sm border-t border-gray-100 pt-3 mt-3">
                      <div><span className="text-gray-500 font-semibold">Materia Orgánica:</span> <span className="font-bold text-gray-900">{ana.materia_organica_porcentaje}%</span></div>
                      <div><span className="text-gray-500 font-semibold">Textura:</span> <span className="font-bold text-gray-900 capitalize">{ana.textura?.toLowerCase() || 'Franco'}</span></div>
                      <div><span className="text-gray-500 font-semibold">Fósforo:</span> <span className="font-bold text-gray-900">{ana.fosforo_ppm} ppm</span></div>
                      <div><span className="text-gray-500 font-semibold">Potasio:</span> <span className="font-bold text-gray-900">{ana.potasio_meq} meq/100g</span></div>
                    </div>
                    {ana.laboratorio && (
                      <p className="text-xs text-gray-400 mt-3 flex items-center gap-1"><CheckCircle2 className="w-3 h-3" /> Realizado por: {ana.laboratorio}</p>
                    )}
                  </div>
                ))}
              </div>
            )}
          </motion.div>
        )}
      </main>

      {/* Modal Nuevo Ciclo Productivo */}
      <AnimatePresence>
        {isModalCicloOpen && (
          <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-gray-900/40 backdrop-blur-sm">
            <motion.div initial={{ opacity: 0, scale: 0.95 }} animate={{ opacity: 1, scale: 1 }} exit={{ opacity: 0, scale: 0.95 }} className="bg-white w-full max-w-md rounded-3xl shadow-2xl overflow-hidden">
              <div className="px-6 py-4 border-b border-gray-100 flex justify-between items-center bg-gray-50/50">
                <h3 className="font-bold text-gray-900">Iniciar Ciclo Productivo</h3>
                <button onClick={() => setIsModalCicloOpen(false)} className="p-1 text-gray-400 hover:bg-gray-200 rounded-full"><X className="w-5 h-5" /></button>
              </div>
              <form onSubmit={handleCreateCiclo} className="p-6 space-y-4">
                <div>
                  <label className="block text-sm font-bold text-gray-700 mb-1">Nombre del Ciclo</label>
                  <input type="text" required value={nuevoCiclo.nombre_ciclo} onChange={e => setNuevoCiclo({...nuevoCiclo, nombre_ciclo: e.target.value})} className="w-full px-4 py-2 bg-gray-50 border border-gray-200 rounded-xl focus:ring-2 focus:ring-rice-emerald outline-none" placeholder="Ej: Cosecha Verano Sur" />
                </div>
                <div className="grid grid-cols-2 gap-4">
                  <div>
                    <label className="block text-sm font-bold text-gray-700 mb-1">Año</label>
                    <input type="number" required value={nuevoCiclo.anio} onChange={e => setNuevoCiclo({...nuevoCiclo, anio: e.target.value})} className="w-full px-4 py-2 bg-gray-50 border border-gray-200 rounded-xl focus:ring-2 focus:ring-rice-emerald outline-none" />
                  </div>
                  <div>
                    <label className="block text-sm font-bold text-gray-700 mb-1">Fecha de Inicio</label>
                    <input type="date" required value={nuevoCiclo.fecha_inicio_real} onChange={e => setNuevoCiclo({...nuevoCiclo, fecha_inicio_real: e.target.value})} className="w-full px-4 py-2 bg-gray-50 border border-gray-200 rounded-xl focus:ring-2 focus:ring-rice-emerald outline-none font-bold text-gray-700" />
                  </div>
                </div>
                <div>
                  <label className="block text-sm font-bold text-gray-700 mb-1">Variedad de Arroz</label>
                  <input type="text" required value={nuevoCiclo.variedad_arroz} onChange={e => setNuevoCiclo({...nuevoCiclo, variedad_arroz: e.target.value})} className="w-full px-4 py-2 bg-gray-50 border border-gray-200 rounded-xl focus:ring-2 focus:ring-rice-emerald outline-none" placeholder="Ej: Fedearroz 68" />
                </div>
                <div>
                  <label className="block text-sm font-bold text-gray-700 mb-1">Presupuesto Estimado (COP)</label>
                  <input type="number" min="0" required value={nuevoCiclo.presupuesto_estimado} onChange={e => setNuevoCiclo({...nuevoCiclo, presupuesto_estimado: e.target.value})} className="w-full px-4 py-2 bg-gray-50 border border-gray-200 rounded-xl focus:ring-2 focus:ring-rice-emerald outline-none" placeholder="Ej: 15000000" />
                </div>



                <button type="submit" disabled={saving} className="w-full mt-4 py-3 bg-rice-green text-white font-bold rounded-xl shadow-lg hover:bg-[#154224] transition-colors flex justify-center items-center gap-2">
                  {saving ? <Loader className="w-5 h-5 animate-spin" /> : 'Guardar Ciclo'}
                </button>
              </form>
            </motion.div>
          </div>
        )}
      </AnimatePresence>

      {/* Modal Nuevo Análisis de Suelo */}
      <AnimatePresence>
        {isModalAnalisisOpen && (
          <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-gray-900/40 backdrop-blur-sm">
            <motion.div initial={{ opacity: 0, scale: 0.95 }} animate={{ opacity: 1, scale: 1 }} exit={{ opacity: 0, scale: 0.95 }} className="bg-white w-full max-w-lg rounded-3xl shadow-2xl overflow-hidden">
              <div className="px-6 py-4 border-b border-gray-100 flex justify-between items-center bg-gray-50/50">
                <h3 className="font-bold text-gray-900">Registrar Análisis de Suelo</h3>
                <button onClick={() => setIsModalAnalisisOpen(false)} className="p-1 text-gray-400 hover:bg-gray-200 rounded-full"><X className="w-5 h-5" /></button>
              </div>
              <form onSubmit={handleCreateAnalisis} className="p-6 space-y-4">
                <div className="grid grid-cols-2 gap-4">
                  <div>
                    <label className="block text-sm font-bold text-gray-700 mb-1">Nivel de pH</label>
                    <input type="number" step="any" min="0" max="14" required value={nuevoAnalisis.ph} onChange={e => setNuevoAnalisis({...nuevoAnalisis, ph: e.target.value})} className="w-full px-4 py-2 bg-gray-50 border border-gray-200 rounded-xl focus:ring-2 focus:ring-blue-500 outline-none" placeholder="Ej: 6.5" />
                  </div>
                  <div>
                    <label className="block text-sm font-bold text-gray-700 mb-1">Materia Orgánica (%)</label>
                    <input type="number" step="any" min="0" required value={nuevoAnalisis.materia_organica_porcentaje} onChange={e => setNuevoAnalisis({...nuevoAnalisis, materia_organica_porcentaje: e.target.value})} className="w-full px-4 py-2 bg-gray-50 border border-gray-200 rounded-xl focus:ring-2 focus:ring-blue-500 outline-none" placeholder="Ej: 3.2" />
                  </div>
                  <div>
                    <label className="block text-sm font-bold text-gray-700 mb-1">Fósforo (P) ppm</label>
                    <input type="number" step="any" min="0" required value={nuevoAnalisis.fosforo_ppm} onChange={e => setNuevoAnalisis({...nuevoAnalisis, fosforo_ppm: e.target.value})} className="w-full px-4 py-2 bg-gray-50 border border-gray-200 rounded-xl focus:ring-2 focus:ring-blue-500 outline-none" placeholder="Ej: 15.0" />
                  </div>
                  <div>
                    <label className="block text-sm font-bold text-gray-700 mb-1">Potasio (K) meq/100g</label>
                    <input type="number" step="any" min="0" required value={nuevoAnalisis.potasio_meq} onChange={e => setNuevoAnalisis({...nuevoAnalisis, potasio_meq: e.target.value})} className="w-full px-4 py-2 bg-gray-50 border border-gray-200 rounded-xl focus:ring-2 focus:ring-blue-500 outline-none" placeholder="Ej: 0.15" />
                  </div>
                  <div>
                    <label className="block text-sm font-bold text-gray-700 mb-1">Textura</label>
                    <select value={nuevoAnalisis.textura} onChange={e => setNuevoAnalisis({...nuevoAnalisis, textura: e.target.value})} className="w-full px-4 py-2 bg-gray-50 border border-gray-200 rounded-xl focus:ring-2 focus:ring-blue-500 outline-none font-semibold text-gray-700">
                      <option value="FRANCO">Franco</option>
                      <option value="ARCILLOSO">Arcilloso</option>
                      <option value="ARENOSO">Arenoso</option>
                    </select>
                  </div>
                  <div>
                    <label className="block text-sm font-bold text-gray-700 mb-1">Laboratorio (Opcional)</label>
                    <input type="text" value={nuevoAnalisis.laboratorio} onChange={e => setNuevoAnalisis({...nuevoAnalisis, laboratorio: e.target.value})} className="w-full px-4 py-2 bg-gray-50 border border-gray-200 rounded-xl focus:ring-2 focus:ring-blue-500 outline-none" placeholder="Ej: Lab. Agrícola" />
                  </div>
                </div>
                <button type="submit" disabled={saving} className="w-full mt-4 py-3 bg-blue-600 text-white font-bold rounded-xl shadow-lg hover:bg-blue-700 transition-colors flex justify-center items-center gap-2">
                  {saving ? <Loader className="w-5 h-5 animate-spin" /> : 'Guardar Análisis'}
                </button>
              </form>
            </motion.div>
          </div>
        )}
      </AnimatePresence>
    </div>
  );
}

import { useState, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { 
  MapPin, Maximize, Plus, Tractor, LogOut, Loader, ArrowLeft, 
  Layers, Compass, Droplet, X, Pencil, Trash2, Search, Filter, TrendingUp 
} from 'lucide-react';
import { useNavigate, useParams, useLocation } from 'react-router-dom';
import axios from 'axios';
import { API_BASE_URL } from '../api';

export default function Lotes() {
  const { fincaId } = useParams();
  const location = useLocation();
  const navigate = useNavigate();

  const [lotes, setLotes] = useState([]);
  const [finca, setFinca] = useState(location.state?.finca || null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  
  // Estado para el modal de nuevo lote
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [saving, setSaving] = useState(false);
  const [validationError, setValidationError] = useState('');
  const [nuevoLote, setNuevoLote] = useState({
    nombre: '',
    area_hectareas: '',
    tipo_suelo: 'FRANCO',
    sistema_produccion: 'RIEGO',
    latitud: '',
    longitud: '',
    estado: 'ACTIVO'
  });

  // Estado para el modal de edición de lote
  const [isEditModalOpen, setIsEditModalOpen] = useState(false);
  const [editingLote, setEditingLote] = useState({
    id: '',
    nombre: '',
    area_hectareas: '',
    tipo_suelo: 'FRANCO',
    sistema_produccion: 'RIEGO',
    latitud: '',
    longitud: '',
    estado: 'ACTIVO'
  });

  // GPS Loading indicators (WOW factor)
  const [gpsLoadingCreate, setGpsLoadingCreate] = useState(false);
  const [gpsLoadingEdit, setGpsLoadingEdit] = useState(false);

  // Filtros Avanzados
  const [searchTerm, setSearchTerm] = useState('');
  const [sizeFilter, setSizeFilter] = useState('ALL'); // 'ALL', 'SMALL', 'MEDIUM', 'LARGE'
  const [soilFilter, setSoilFilter] = useState('ALL'); // 'ALL', 'FRANCO', 'ARCILLOSO', 'ARENOSO'
  const [prodFilter, setProdFilter] = useState('ALL'); // 'ALL', 'RIEGO', 'SECANO'
  const [statusFilter, setStatusFilter] = useState('ALL'); // 'ALL', 'ACTIVO', 'PREPARACION', 'EN_CICLO', 'COSECHADO', 'DESCANSO'

  const username = localStorage.getItem('username');
  const rol = localStorage.getItem('rol');
  const token = localStorage.getItem('token');

  const fetchFincaDetails = async () => {
    try {
      const response = await axios.get(`${API_BASE_URL}/api/fincas/${fincaId}/`, {
        headers: { Authorization: `Bearer ${token}` }
      });
      setFinca(response.data);
      fetchLotes();
    } catch (err) {
      console.error(err);
      setError('No se pudo cargar la información de la finca.');
      setLoading(false);
    }
  };

  const fetchLotes = async () => {
    try {
      setLoading(true);
      const response = await axios.get(`${API_BASE_URL}/api/lotes/?finca_id=${fincaId}`, {
        headers: { Authorization: `Bearer ${token}` }
      });
      setLotes(response.data);
    } catch (err) {
      console.error(err);
      setError('No se pudieron cargar los lotes de esta finca.');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    if (!token) {
      navigate('/login');
      return;
    }
    
    if (!finca) {
      fetchFincaDetails();
    } else {
      fetchLotes();
    }
  }, [fincaId, token]);

  const handleLogout = () => {
    localStorage.clear();
    navigate('/login');
  };

  // Calcular áreas asignadas
  const areaTotalFinca = finca ? parseFloat(finca.area_total_ha) : 0;
  const areaAsignadaLotes = lotes.reduce((sum, lote) => sum + parseFloat(lote.area_hectareas), 0);
  const areaDisponible = Math.max(0, areaTotalFinca - areaAsignadaLotes);
  const porcentajeAsignado = Math.min(100, (areaAsignadaLotes / areaTotalFinca) * 100);

  const handleCreateLote = async (e) => {
    e.preventDefault();
    setValidationError('');
    
    const areaInput = parseFloat(nuevoLote.area_hectareas);
    
    // Validación cruzada local
    if (areaInput > areaDisponible) {
      setValidationError(
        `No puedes registrar este lote. El área ingresada (${areaInput} ha) supera el área restante disponible en la finca (${areaDisponible.toFixed(2)} ha).`
      );
      return;
    }

    setSaving(true);
    try {
      const payload = {
        finca: parseInt(fincaId),
        nombre: nuevoLote.nombre,
        area_hectareas: areaInput,
        tipo_suelo: nuevoLote.tipo_suelo,
        sistema_produccion: nuevoLote.sistema_produccion,
        latitud: nuevoLote.latitud ? parseFloat(nuevoLote.latitud) : null,
        longitud: nuevoLote.longitud ? parseFloat(nuevoLote.longitud) : null,
        estado: nuevoLote.estado
      };

      const response = await axios.post(`${API_BASE_URL}/api/lotes/`, payload, {
        headers: { Authorization: `Bearer ${token}` }
      });

      setLotes([response.data, ...lotes]);
      setIsModalOpen(false);
      setNuevoLote({
        nombre: '',
        area_hectareas: '',
        tipo_suelo: 'FRANCO',
        sistema_produccion: 'RIEGO',
        latitud: '',
        longitud: '',
        estado: 'ACTIVO'
      });
    } catch (err) {
      console.error(err);
      if (err.response?.data?.area_hectareas) {
        setValidationError(err.response.data.area_hectareas[0]);
      } else {
        setValidationError('Ocurrió un error al registrar el lote en el servidor.');
      }
    } finally {
      setSaving(false);
    }
  };

  const handleOpenEditLoteModal = (lote) => {
    setEditingLote({
      id: lote.id,
      nombre: lote.nombre,
      area_hectareas: lote.area_hectareas,
      tipo_suelo: lote.tipo_suelo,
      sistema_produccion: lote.sistema_produccion,
      latitud: lote.latitud || '',
      longitud: lote.longitud || '',
      estado: lote.estado
    });
    setIsEditModalOpen(true);
  };

  const handleEditLote = async (e) => {
    e.preventDefault();
    setValidationError('');

    const areaInput = parseFloat(editingLote.area_hectareas);
    const loteOriginal = lotes.find(l => l.id === editingLote.id);
    const areaOriginal = loteOriginal ? parseFloat(loteOriginal.area_hectareas) : 0;
    const maxAreaPermitida = areaDisponible + areaOriginal;

    if (areaInput > maxAreaPermitida) {
      setValidationError(
        `No puedes actualizar el lote. El área ingresada (${areaInput} ha) supera el límite máximo disponible para este lote (${maxAreaPermitida.toFixed(2)} ha).`
      );
      return;
    }

    setSaving(true);
    try {
      const payload = {
        finca: parseInt(fincaId),
        nombre: editingLote.nombre,
        area_hectareas: areaInput,
        tipo_suelo: editingLote.tipo_suelo,
        sistema_produccion: editingLote.sistema_produccion,
        latitud: editingLote.latitud ? parseFloat(editingLote.latitud) : null,
        longitud: editingLote.longitud ? parseFloat(editingLote.longitud) : null,
        estado: editingLote.estado
      };

      const response = await axios.put(`${API_BASE_URL}/api/lotes/${editingLote.id}/`, payload, {
        headers: { Authorization: `Bearer ${token}` }
      });

      setLotes(lotes.map(l => l.id === editingLote.id ? response.data : l));
      setIsEditModalOpen(false);
    } catch (err) {
      console.error("Error al editar lote:", err.response?.data);
      if (err.response?.data?.area_hectareas) {
        setValidationError(err.response.data.area_hectareas[0]);
      } else {
        setValidationError('Ocurrió un error al actualizar el lote en el servidor.');
      }
    } finally {
      setSaving(false);
    }
  };

  const handleDeleteLote = async (lote) => {
    const confirmacion = window.confirm(`⚠️ ADVERTENCIA DE ELIMINACIÓN DE LOTE:
¿Estás completamente seguro de que deseas eliminar el lote "${lote.nombre}"?

Esta acción eliminará de forma permanente este lote y TODOS sus análisis de suelo y ciclos de cultivo asociados de forma irreversible. Esta acción no se puede deshacer.`);

    if (!confirmacion) return;

    try {
      await axios.delete(`${API_BASE_URL}/api/lotes/${lote.id}/`, {
        headers: { Authorization: `Bearer ${token}` }
      });
      setLotes(lotes.filter(l => l.id !== lote.id));
    } catch (err) {
      console.error("Error al eliminar lote:", err.response?.data);
      alert('Error al intentar eliminar el lote. Verifica tus permisos de red.');
    }
  };

  // Geolocalización Nativa para Lotes
  const capturarGPS = (isEdit = false) => {
    if (!navigator.geolocation) {
      alert("Tu navegador no soporta geolocalización.");
      return;
    }
    
    if (isEdit) {
      setGpsLoadingEdit(true);
      navigator.geolocation.getCurrentPosition(
        (position) => {
          setEditingLote(prev => ({
            ...prev,
            latitud: position.coords.latitude.toFixed(6),
            longitud: position.coords.longitude.toFixed(6)
          }));
          setGpsLoadingEdit(false);
        },
        (err) => {
          console.error(err);
          setGpsLoadingEdit(false);
          alert("No se pudo obtener la geolocalización. Otorga permisos de ubicación.");
        }
      );
    } else {
      setGpsLoadingCreate(true);
      navigator.geolocation.getCurrentPosition(
        (position) => {
          setNuevoLote(prev => ({
            ...prev,
            latitud: position.coords.latitude.toFixed(6),
            longitud: position.coords.longitude.toFixed(6)
          }));
          setGpsLoadingCreate(false);
        },
        (err) => {
          console.error(err);
          setGpsLoadingCreate(false);
          alert("No se pudo obtener la geolocalización. Otorga permisos de ubicación.");
        }
      );
    }
  };

  // Mapear etiquetas de estado a colores premium en Tono Claro
  const getEstadoBadge = (estado) => {
    const estilos = {
      'ACTIVO': 'bg-emerald-50 text-emerald-700 border border-emerald-250 border-emerald-200',
      'PREPARACION': 'bg-amber-50 text-amber-700 border border-amber-200',
      'EN_CICLO': 'bg-blue-50 text-blue-700 border border-blue-200',
      'COSECHADO': 'bg-purple-50 text-purple-700 border border-purple-200',
      'DESCANSO': 'bg-gray-100 text-gray-700 border border-gray-300'
    };
    return estilos[estado] || 'bg-gray-50 text-gray-600';
  };

  // Lógica de filtrado reactivo de lotes
  const filteredLotes = lotes.filter(lote => {
    // 1. Texto (Nombre)
    const textMatch = lote.nombre.toLowerCase().includes(searchTerm.toLowerCase());

    // 2. Tamaño Hectáreas
    const area = parseFloat(lote.area_hectareas || 0);
    let sizeMatch = true;
    if (sizeFilter === 'SMALL') sizeMatch = area < 2;
    else if (sizeFilter === 'MEDIUM') sizeMatch = area >= 2 && area <= 5;
    else if (sizeFilter === 'LARGE') sizeMatch = area > 5;

    // 3. Tipo Suelo
    const soilMatch = soilFilter === 'ALL' || lote.tipo_suelo === soilFilter;

    // 4. Sistema Producción
    const prodMatch = prodFilter === 'ALL' || lote.sistema_produccion === prodFilter;

    // 5. Estado
    const statusMatch = statusFilter === 'ALL' || lote.estado === statusFilter;

    return textMatch && sizeMatch && soilMatch && prodMatch && statusMatch;
  });

  return (
    <div className="min-h-screen bg-gradient-to-br from-[#F4F9F6] via-[#FAFDFB] to-[#F0F5F2] text-gray-800 font-sans pb-12">
      {/* Top Navbar */}
      <nav className="backdrop-blur-md bg-[#FAFDFB]/85 border-b border-emerald-100/80 sticky top-0 z-40 shadow-sm">
        <div className="max-w-7xl mx-auto px-6 h-20 flex items-center justify-between">
          <div className="flex items-center gap-3 cursor-pointer" onClick={() => navigate('/fincas')}>
            <div className="w-10 h-10 bg-gradient-to-tr from-[#1E5631] to-[#4C9A2A] rounded-xl flex items-center justify-center shadow-md">
              <Tractor className="w-5 h-5 text-white" />
            </div>
            <span className="text-xl font-black text-gray-900 tracking-tight">SIG-ARROZ</span>
          </div>
          
          <div className="flex items-center gap-4">
            <button
              onClick={() => navigate('/historial-produccion', { state: { fincaId } })}
              className="flex items-center gap-1.5 px-4 py-2 bg-emerald-50 hover:bg-emerald-100 border border-emerald-200 text-emerald-800 rounded-xl text-xs font-bold transition-all shadow-sm"
              title="Ver Historial de Rendimientos"
            >
              <TrendingUp className="w-4 h-4 text-emerald-700" />
              <span>Rendimientos</span>
            </button>

            <div className="text-right hidden sm:block">
              <p className="text-sm font-black text-gray-800">{username}</p>
              <p className="text-2xs font-extrabold text-[#b8952b] uppercase tracking-wider">{rol}</p>
            </div>
            <button 
              onClick={handleLogout}
              className="p-2.5 text-gray-500 hover:text-red-600 hover:bg-red-50 rounded-xl transition-all border border-transparent hover:border-red-100"
              title="Cerrar Sesión"
            >
              <LogOut className="w-5 h-5" />
            </button>
          </div>
        </div>
      </nav>

      {/* Main Content */}
      <main className="max-w-7xl mx-auto px-6 py-8 space-y-6">
        
        {/* Botón de regreso */}
        <button 
          onClick={() => navigate('/fincas')}
          className="flex items-center gap-2 text-gray-500 hover:text-emerald-700 font-bold transition-all group"
        >
          <ArrowLeft className="w-5 h-5 transition-transform group-hover:-translate-x-1" />
          Volver a Fincas
        </button>

        {/* Finca Info Card */}
        {finca && (
          <motion.div 
            initial={{ opacity: 0, y: -10 }}
            animate={{ opacity: 1, y: 0 }}
            className="bg-white border border-emerald-100 rounded-3xl p-6 sm:p-8 shadow-sm relative overflow-hidden"
          >
            <div className="absolute top-0 right-0 w-32 h-32 bg-emerald-100/10 rounded-bl-full -mr-4 -mt-4"></div>
            
            <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-6 relative z-10">
              <div>
                <span className="text-xs font-bold text-emerald-700 uppercase tracking-widest bg-emerald-50 border border-emerald-100 px-3 py-1 rounded-full">Propiedad Seleccionada</span>
                <h1 className="text-3xl font-black text-gray-900 mt-3 tracking-tight">{finca.nombre}</h1>
                <p className="text-gray-500 font-medium mt-1.5 flex items-center gap-1.5 text-sm">
                  <MapPin className="w-4 h-4 text-emerald-600" />
                  {finca.ubicacion_municipio}, {finca.ubicacion_departamento}
                </p>
              </div>

              {/* Hectares Progress bar (WOW Factor) */}
              <div className="w-full md:w-80 bg-[#F8FAF9] p-4 rounded-2xl border border-emerald-100/40">
                <div className="flex justify-between items-center text-xs font-bold text-gray-700 mb-2">
                  <span>Área Asignada a Lotes</span>
                  <span className="text-emerald-700 font-extrabold">{areaAsignadaLotes.toFixed(1)} / {areaTotalFinca} Ha</span>
                </div>
                <div className="w-full bg-gray-200 h-3 rounded-full overflow-hidden">
                  <div 
                    className="bg-emerald-600 h-full rounded-full transition-all duration-500" 
                    style={{ width: `${porcentajeAsignado}%` }}
                  />
                </div>
                <p className="text-2xs text-gray-400 font-bold mt-2 text-right uppercase tracking-wider">
                  {areaDisponible.toFixed(1)} Hectáreas Libres
                </p>
              </div>
            </div>
          </motion.div>
        )}

        {/* 2. Barra de Búsqueda y Filtros Avanzados para Lotes */}
        <section className="bg-white border border-emerald-100 rounded-3xl p-6 shadow-sm space-y-6">
          <div className="flex items-center gap-2 pb-4 border-b border-emerald-50">
            <Filter className="w-5 h-5 text-emerald-600" />
            <div>
              <h3 className="text-base font-black text-gray-900">Búsqueda y Filtros de Lotes</h3>
              <p className="text-2xs text-gray-500 font-bold">Filtra y clasifica tus lotes en tiempo real según características y tamaño de hectáreas</p>
            </div>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-12 gap-4 items-center">
            {/* Buscador por Nombre */}
            <div className="md:col-span-3 flex flex-col gap-1">
              <label className="text-2xs font-extrabold text-gray-500 uppercase tracking-wider pl-1">Buscar Lote:</label>
              <div className="relative w-full">
                <Search className="absolute left-3.5 top-3.5 w-4.5 h-4.5 text-gray-400" />
                <input 
                  type="text"
                  value={searchTerm}
                  onChange={(e) => setSearchTerm(e.target.value)}
                  placeholder="Buscar por nombre..."
                  className="w-full pl-11 pr-4 py-3 bg-[#F8FAF9] border border-gray-200 rounded-xl text-xs focus:border-emerald-500 focus:outline-none transition-all font-semibold text-gray-900"
                />
              </div>
            </div>

            {/* Filtro Hectáreas */}
            <div className="md:col-span-3 flex flex-col gap-1">
              <label className="text-2xs font-extrabold text-gray-500 uppercase tracking-wider pl-1">Hectáreas:</label>
              <select
                value={sizeFilter}
                onChange={(e) => setSizeFilter(e.target.value)}
                className="w-full px-3 py-3 bg-[#F8FAF9] border border-gray-200 rounded-xl text-2xs font-bold text-gray-700 cursor-pointer focus:outline-none focus:border-emerald-500"
              >
                <option value="ALL">Cualquier tamaño</option>
                <option value="SMALL">Pequeños (&lt; 2 Ha)</option>
                <option value="MEDIUM">Medianos (2 - 5 Ha)</option>
                <option value="LARGE">Grandes (&gt; 5 Ha)</option>
              </select>
            </div>

            {/* Tipo Suelo */}
            <div className="md:col-span-2 flex flex-col gap-1">
              <label className="text-2xs font-extrabold text-gray-500 uppercase tracking-wider pl-1">Suelo:</label>
              <select
                value={soilFilter}
                onChange={(e) => setSoilFilter(e.target.value)}
                className="w-full px-2 py-3 bg-[#F8FAF9] border border-gray-200 rounded-xl text-2xs font-bold text-gray-700 cursor-pointer focus:outline-none focus:border-emerald-500"
              >
                <option value="ALL">Todos</option>
                <option value="FRANCO">Franco</option>
                <option value="ARCILLOSO">Arcilloso</option>
                <option value="ARENOSO">Arenoso</option>
              </select>
            </div>

            {/* Sistema Producción */}
            <div className="md:col-span-2 flex flex-col gap-1">
              <label className="text-2xs font-extrabold text-gray-500 uppercase tracking-wider pl-1">Cultivo:</label>
              <select
                value={prodFilter}
                onChange={(e) => setProdFilter(e.target.value)}
                className="w-full px-2 py-3 bg-[#F8FAF9] border border-gray-200 rounded-xl text-2xs font-bold text-gray-700 cursor-pointer focus:outline-none focus:border-emerald-500"
              >
                <option value="ALL">Todos</option>
                <option value="RIEGO">Riego</option>
                <option value="SECANO">Secano</option>
              </select>
            </div>

            {/* Estado */}
            <div className="md:col-span-2 flex flex-col gap-1">
              <label className="text-2xs font-extrabold text-gray-500 uppercase tracking-wider pl-1">Estado:</label>
              <select
                value={statusFilter}
                onChange={(e) => setStatusFilter(e.target.value)}
                className="w-full px-2 py-3 bg-[#F8FAF9] border border-gray-200 rounded-xl text-2xs font-bold text-gray-700 cursor-pointer focus:outline-none focus:border-emerald-500"
              >
                <option value="ALL">Todos</option>
                <option value="ACTIVO">Disponible</option>
                <option value="PREPARACION">En Preparación</option>
                <option value="EN_CICLO">En Ciclo</option>
                <option value="COSECHADO">Cosechado</option>
                <option value="DESCANSO">En Descanso</option>
              </select>
            </div>
          </div>
        </section>

        {/* Header grid */}
        <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
          <div>
            <h2 className="text-2xl font-black text-gray-950 tracking-tight">Lotes del Cultivo</h2>
            <p className="text-xs text-gray-500 font-semibold mt-1">
              Visualizando {filteredLotes.length} de {lotes.length} lotes mapeados en esta finca
            </p>
          </div>
          
          {rol !== 'TECNICO' && finca && areaDisponible > 0.1 && (
            <motion.button
              whileHover={{ scale: 1.02 }}
              whileTap={{ scale: 0.98 }}
              onClick={() => setIsModalOpen(true)}
              className="bg-gradient-to-r from-emerald-600 to-[#4C9A2A] hover:from-emerald-500 hover:to-emerald-400 text-white px-5 py-3 rounded-xl font-bold shadow-md hover:shadow-lg transition-all flex items-center gap-2"
            >
              <Plus className="w-5 h-5" />
              Añadir Lote
            </motion.button>
          )}
        </div>

        {/* Grid / Listado */}
        {loading ? (
          <div className="flex flex-col items-center justify-center py-20 bg-white border border-emerald-100 rounded-3xl">
            <Loader className="w-10 h-10 text-emerald-600 animate-spin mb-4" />
            <p className="text-sm text-gray-500 font-bold">Cargando los lotes de la finca...</p>
          </div>
        ) : error ? (
          <div className="bg-red-50 border border-red-200 text-red-700 p-4 rounded-xl text-center font-bold text-sm">
            {error}
          </div>
        ) : filteredLotes.length === 0 ? (
          <div className="bg-white border border-emerald-100 rounded-3xl p-12 text-center shadow-sm">
            <div className="w-20 h-20 bg-emerald-50 border border-emerald-100 rounded-full flex items-center justify-center mx-auto mb-4">
              <Layers className="w-10 h-10 text-emerald-600" />
            </div>
            <h3 className="text-lg font-black text-gray-950 mb-1">No se encontraron lotes</h3>
            <p className="text-xs text-gray-500 mb-6 max-w-sm mx-auto font-medium">
              Prueba modificando los filtros o agregando un nuevo lote a la finca arrocera.
            </p>
            {rol !== 'TECNICO' && lotes.length === 0 && (
              <button 
                onClick={() => setIsModalOpen(true)}
                className="text-emerald-700 font-black hover:text-emerald-800 hover:underline transition-all"
              >
                + Registrar mi primer lote
              </button>
            )}
          </div>
        ) : (
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
            {filteredLotes.map((lote) => (
              <motion.div
                key={lote.id}
                initial={{ opacity: 0, y: 10 }}
                animate={{ opacity: 1, y: 0 }}
                whileHover={{ y: -4 }}
                onClick={() => navigate(`/lotes/${lote.id}/gestion`, { state: { lote, finca } })}
                className="bg-white border border-emerald-100/60 rounded-3xl p-6 shadow-sm hover:shadow-md relative overflow-hidden group cursor-pointer transition-all duration-300"
              >
                <div className="flex justify-between items-start mb-4">
                  <h3 className="text-xl font-black text-gray-900 group-hover:text-emerald-700 transition-colors pr-2">
                    {lote.nombre}
                  </h3>
                  <span className={`text-3xs font-extrabold uppercase tracking-wider px-2.5 py-1 rounded-full shrink-0 ${getEstadoBadge(lote.estado)}`}>
                    {lote.estado === 'ACTIVO' ? 'DISPONIBLE' : lote.estado === 'PREPARACION' ? 'EN PREPARACION' : lote.estado}
                  </span>
                </div>

                <div className="space-y-3 mt-4">
                  <div className="flex items-center justify-between text-xs py-1.5 border-b border-emerald-50">
                    <span className="text-gray-500 font-bold flex items-center gap-1.5"><Maximize className="w-4 h-4 text-emerald-600" /> Área</span>
                    <span className="font-extrabold text-[#b8952b]">{lote.area_hectareas} Ha</span>
                  </div>

                  <div className="flex items-center justify-between text-xs py-1.5 border-b border-emerald-50">
                    <span className="text-gray-500 font-bold flex items-center gap-1.5"><Layers className="w-4 h-4 text-emerald-600" /> Tipo Suelo</span>
                    <span className="font-bold text-gray-800 capitalize">{lote.tipo_suelo.toLowerCase()}</span>
                  </div>

                  <div className="flex items-center justify-between text-xs py-1.5 border-b border-emerald-50">
                    <span className="text-gray-500 font-bold flex items-center gap-1.5"><Droplet className="w-4 h-4 text-emerald-600" /> Producción</span>
                    <span className="font-bold text-gray-800 capitalize">{lote.sistema_produccion.toLowerCase()}</span>
                  </div>

                  {lote.latitud && lote.longitud ? (
                    <div className="flex items-center justify-between text-xs py-1.5">
                      <span className="text-gray-500 font-bold flex items-center gap-1.5"><Compass className="w-4 h-4 text-emerald-600" /> Ubicación GPS</span>
                      <span className="font-extrabold text-emerald-700">{Number(lote.latitud).toFixed(4)}, {Number(lote.longitud).toFixed(4)}</span>
                    </div>
                  ) : (
                    <div className="flex items-center justify-between text-xs py-1.5">
                      <span className="text-gray-500 font-bold flex items-center gap-1.5"><Compass className="w-4 h-4 text-emerald-600" /> Ubicación GPS</span>
                      <span className="text-gray-400 text-xs font-semibold italic">Sin coordenadas</span>
                    </div>
                  )}
                </div>

                <div className="mt-6 pt-4 border-t border-emerald-50 flex justify-between items-center">
                  <span className="text-xs font-bold text-emerald-700 group-hover:text-emerald-800 group-hover:underline cursor-pointer">Ver Ciclos de Cultivo →</span>
                  
                  {rol !== 'TECNICO' && (
                    <div className="flex gap-1.5 opacity-0 group-hover:opacity-100 transition-opacity duration-300">
                      <button
                        onClick={(e) => {
                          e.stopPropagation();
                          handleOpenEditLoteModal(lote);
                        }}
                        className="p-2 bg-[#FAFDFB] border border-emerald-100 text-gray-500 hover:text-blue-600 hover:bg-blue-50 rounded-lg transition-colors flex items-center justify-center shadow-sm"
                        title="Editar Lote"
                      >
                        <Pencil className="w-3.5 h-3.5" />
                      </button>
                      <button
                        onClick={(e) => {
                          e.stopPropagation();
                          handleDeleteLote(lote);
                        }}
                        className="p-2 bg-[#FAFDFB] border border-emerald-100 text-gray-500 hover:text-red-650 hover:text-red-600 hover:bg-red-50 rounded-lg transition-colors flex items-center justify-center shadow-sm"
                        title="Eliminar Lote"
                      >
                        <Trash2 className="w-3.5 h-3.5" />
                      </button>
                    </div>
                  )}
                </div>
              </motion.div>
            ))}
          </div>
        )}
      </main>

      {/* Modal Crear Lote */}
      <AnimatePresence>
        {isModalOpen && (
          <div className="fixed inset-0 z-50 flex items-center justify-center p-4">
            <motion.div 
              initial={{ opacity: 0 }} 
              animate={{ opacity: 1 }} 
              exit={{ opacity: 0 }}
              className="absolute inset-0 bg-[#0D1A12]/40 backdrop-blur-sm"
              onClick={() => setIsModalOpen(false)}
            />
            
            <motion.div 
              initial={{ opacity: 0, scale: 0.95, y: 20 }}
              animate={{ opacity: 1, scale: 1, y: 0 }}
              exit={{ opacity: 0, scale: 0.95, y: 20 }}
              className="bg-white w-full max-w-lg rounded-3xl shadow-2xl relative z-10 overflow-hidden border border-emerald-100"
            >
              <div className="px-6 py-5 border-b border-emerald-50 flex justify-between items-center bg-[#FAFDFB]">
                <h3 className="text-lg font-black text-gray-900">Registrar Nuevo Lote</h3>
                <button onClick={() => setIsModalOpen(false)} className="p-2 text-gray-400 hover:text-gray-600 hover:bg-gray-100 rounded-full transition-colors">
                  <X className="w-5 h-5" />
                </button>
              </div>

              {validationError && (
                <div className="mx-6 mt-4 bg-red-50 border border-red-200 text-red-700 px-4 py-3 rounded-xl text-xs font-bold">
                  {validationError}
                </div>
              )}

              <form onSubmit={handleCreateLote} className="p-6 space-y-4 text-gray-800">
                <div>
                  <label className="block text-2xs font-extrabold text-gray-500 uppercase tracking-wider mb-1">Nombre del Lote</label>
                  <input 
                    type="text" required
                    value={nuevoLote.nombre}
                    onChange={(e) => setNuevoLote({...nuevoLote, nombre: e.target.value})}
                    className="w-full px-4 py-3 bg-[#F8FAF9] border border-gray-200 rounded-xl focus:ring-2 focus:ring-emerald-500 focus:border-transparent outline-none transition-all font-semibold text-gray-900"
                    placeholder="Ej: Lote Norte A-1"
                  />
                </div>
                
                <div className="grid grid-cols-2 gap-4">
                  <div>
                    <label className="block text-2xs font-extrabold text-gray-500 uppercase tracking-wider mb-1">Área (Hectáreas)</label>
                    <input 
                      type="number" step="0.01" min="0.1" required
                      value={nuevoLote.area_hectareas}
                      onChange={(e) => setNuevoLote({...nuevoLote, area_hectareas: e.target.value})}
                      className="w-full px-4 py-3 bg-[#F8FAF9] border border-gray-200 rounded-xl focus:ring-2 focus:ring-emerald-500 outline-none transition-all font-semibold text-gray-900"
                      placeholder="Ej: 5.2"
                    />
                  </div>
                  <div>
                    <label className="block text-2xs font-extrabold text-gray-500 uppercase tracking-wider mb-1">Estado Inicial</label>
                    <select
                      value={nuevoLote.estado}
                      onChange={(e) => setNuevoLote({...nuevoLote, estado: e.target.value})}
                      className="w-full px-4 py-3 bg-[#F8FAF9] border border-gray-200 rounded-xl focus:ring-2 focus:ring-emerald-500 outline-none transition-all font-bold text-gray-700 cursor-pointer"
                    >
                      <option value="ACTIVO">Disponible</option>
                      <option value="PREPARACION">En Preparación</option>
                      <option value="DESCANSO">En Descanso</option>
                    </select>
                  </div>
                </div>

                <div className="grid grid-cols-2 gap-4">
                  <div>
                    <label className="block text-2xs font-extrabold text-gray-500 uppercase tracking-wider mb-1">Tipo de Suelo</label>
                    <select
                      value={nuevoLote.tipo_suelo}
                      onChange={(e) => setNuevoLote({...nuevoLote, tipo_suelo: e.target.value})}
                      className="w-full px-4 py-3 bg-[#F8FAF9] border border-gray-200 rounded-xl focus:ring-2 focus:ring-emerald-500 outline-none transition-all font-bold text-gray-700 cursor-pointer"
                    >
                      <option value="FRANCO">Franco</option>
                      <option value="ARCILLOSO">Arcilloso</option>
                      <option value="ARENOSO">Arenoso</option>
                    </select>
                  </div>
                  <div>
                    <label className="block text-2xs font-extrabold text-gray-500 uppercase tracking-wider mb-1">Sistema de Producción</label>
                    <select
                      value={nuevoLote.sistema_produccion}
                      onChange={(e) => setNuevoLote({...nuevoLote, sistema_produccion: e.target.value})}
                      className="w-full px-4 py-3 bg-[#F8FAF9] border border-gray-200 rounded-xl focus:ring-2 focus:ring-emerald-500 outline-none transition-all font-bold text-gray-700 cursor-pointer"
                    >
                      <option value="RIEGO">Riego</option>
                      <option value="SECANO">Secano</option>
                    </select>
                  </div>
                </div>

                {/* Captura de GPS Nativo */}
                <div className="pt-2">
                  <button
                    type="button"
                    onClick={() => capturarGPS(false)}
                    className="w-full py-3 bg-emerald-50 hover:bg-emerald-100 text-emerald-800 border border-emerald-200 hover:border-emerald-300 rounded-2xl text-xs font-bold transition-all flex items-center justify-center gap-2 shadow-sm"
                  >
                    <Compass className={`w-4.5 h-4.5 text-emerald-600 ${gpsLoadingCreate ? 'animate-spin' : ''}`} />
                    {gpsLoadingCreate ? 'Accediendo a satélites GPS...' : 'Capturar Coordenadas GPS del Teléfono'}
                  </button>
                </div>

                <div className="grid grid-cols-2 gap-4">
                  <div>
                    <label className="block text-2xs font-extrabold text-gray-500 uppercase tracking-wider mb-1">Latitud GPS</label>
                    <input 
                      type="number" step="0.000001"
                      value={nuevoLote.latitud}
                      onChange={(e) => setNuevoLote({...nuevoLote, latitud: e.target.value})}
                      className="w-full px-4 py-3 bg-[#F8FAF9] border border-gray-200 rounded-xl focus:ring-2 focus:ring-emerald-500 outline-none transition-all font-semibold text-gray-900"
                      placeholder="Ej: 4.123456"
                    />
                  </div>
                  <div>
                    <label className="block text-2xs font-extrabold text-gray-500 uppercase tracking-wider mb-1">Longitud GPS</label>
                    <input 
                      type="number" step="0.000001"
                      value={nuevoLote.longitud}
                      onChange={(e) => setNuevoLote({...nuevoLote, longitud: e.target.value})}
                      className="w-full px-4 py-3 bg-[#F8FAF9] border border-gray-200 rounded-xl focus:ring-2 focus:ring-emerald-500 outline-none transition-all font-semibold text-gray-900"
                      placeholder="Ej: -74.987654"
                    />
                  </div>
                </div>

                <div className="mt-8 flex gap-3 pt-4 border-t border-emerald-50">
                  <button 
                    type="button" 
                    onClick={() => setIsModalOpen(false)}
                    className="flex-1 px-4 py-3 text-gray-600 font-bold bg-[#F8FAF9] border border-gray-200 hover:bg-gray-100 rounded-xl transition-all"
                  >
                    Cancelar
                  </button>
                  <button 
                    type="submit" 
                    disabled={saving}
                    className="flex-1 px-4 py-3 text-white font-bold bg-gradient-to-r from-emerald-600 to-[#4C9A2A] hover:from-emerald-500 hover:to-emerald-400 rounded-xl shadow-md transition-all flex justify-center items-center gap-2"
                  >
                    {saving ? <><Loader className="w-5 h-5 animate-spin" /> Guardando</> : 'Registrar Lote'}
                  </button>
                </div>
              </form>
            </motion.div>
          </div>
        )}
      </AnimatePresence>

      {/* Modal Editar Lote */}
      <AnimatePresence>
        {isEditModalOpen && (
          <div className="fixed inset-0 z-50 flex items-center justify-center p-4">
            <motion.div 
              initial={{ opacity: 0 }} 
              animate={{ opacity: 1 }} 
              exit={{ opacity: 0 }}
              className="absolute inset-0 bg-[#0D1A12]/40 backdrop-blur-sm"
              onClick={() => setIsEditModalOpen(false)}
            />
            
            <motion.div 
              initial={{ opacity: 0, scale: 0.95, y: 20 }}
              animate={{ opacity: 1, scale: 1, y: 0 }}
              exit={{ opacity: 0, scale: 0.95, y: 20 }}
              className="bg-white w-full max-w-lg rounded-3xl shadow-2xl relative z-10 overflow-hidden border border-emerald-100"
            >
              <div className="px-6 py-5 border-b border-emerald-50 flex justify-between items-center bg-[#FAFDFB]">
                <h3 className="text-lg font-black text-gray-900">Editar Lote</h3>
                <button onClick={() => setIsEditModalOpen(false)} className="p-2 text-gray-400 hover:text-gray-600 hover:bg-gray-100 rounded-full transition-colors">
                  <X className="w-5 h-5" />
                </button>
              </div>

              {validationError && (
                <div className="mx-6 mt-4 bg-red-50 border border-red-200 text-red-700 px-4 py-3 rounded-xl text-xs font-bold">
                  {validationError}
                </div>
              )}

              <form onSubmit={handleEditLote} className="p-6 space-y-4 text-gray-800">
                <div>
                  <label className="block text-2xs font-extrabold text-gray-500 uppercase tracking-wider mb-1">Nombre del Lote</label>
                  <input 
                    type="text" required
                    value={editingLote.nombre}
                    onChange={(e) => setEditingLote({...editingLote, nombre: e.target.value})}
                    className="w-full px-4 py-3 bg-[#F8FAF9] border border-gray-200 rounded-xl focus:ring-2 focus:ring-emerald-500 focus:border-transparent outline-none transition-all font-semibold text-gray-900"
                  />
                </div>
                
                <div className="grid grid-cols-2 gap-4">
                  <div>
                    <label className="block text-2xs font-extrabold text-gray-500 uppercase tracking-wider mb-1">Área (Hectáreas)</label>
                    <input 
                      type="number" step="0.01" min="0.1" required
                      value={editingLote.area_hectareas}
                      onChange={(e) => setEditingLote({...editingLote, area_hectareas: e.target.value})}
                      className="w-full px-4 py-3 bg-[#F8FAF9] border border-gray-200 rounded-xl focus:ring-2 focus:ring-emerald-500 outline-none transition-all font-semibold text-gray-900"
                    />
                  </div>
                  <div>
                    <label className="block text-2xs font-extrabold text-gray-500 uppercase tracking-wider mb-1">Estado</label>
                    <select
                      value={editingLote.estado}
                      onChange={(e) => setEditingLote({...editingLote, estado: e.target.value})}
                      className="w-full px-4 py-3 bg-[#F8FAF9] border border-gray-200 rounded-xl focus:ring-2 focus:ring-emerald-500 outline-none transition-all font-bold text-gray-700 cursor-pointer"
                    >
                      <option value="ACTIVO">Disponible</option>
                      <option value="PREPARACION">En Preparación</option>
                      <option value="EN_CICLO">En Ciclo</option>
                      <option value="COSECHADO">Cosechado</option>
                      <option value="DESCANSO">En Descanso</option>
                    </select>
                  </div>
                </div>

                <div className="grid grid-cols-2 gap-4">
                  <div>
                    <label className="block text-2xs font-extrabold text-gray-500 uppercase tracking-wider mb-1">Tipo de Suelo</label>
                    <select
                      value={editingLote.tipo_suelo}
                      onChange={(e) => setEditingLote({...editingLote, tipo_suelo: e.target.value})}
                      className="w-full px-4 py-3 bg-[#F8FAF9] border border-gray-200 rounded-xl focus:ring-2 focus:ring-emerald-500 outline-none transition-all font-bold text-gray-700 cursor-pointer"
                    >
                      <option value="FRANCO">Franco</option>
                      <option value="ARCILLOSO">Arcilloso</option>
                      <option value="ARENOSO">Arenoso</option>
                    </select>
                  </div>
                  <div>
                    <label className="block text-2xs font-extrabold text-gray-500 uppercase tracking-wider mb-1">Sistema de Producción</label>
                    <select
                      value={editingLote.sistema_produccion}
                      onChange={(e) => setEditingLote({...editingLote, sistema_produccion: e.target.value})}
                      className="w-full px-4 py-3 bg-[#F8FAF9] border border-gray-200 rounded-xl focus:ring-2 focus:ring-emerald-500 outline-none transition-all font-bold text-gray-700 cursor-pointer"
                    >
                      <option value="RIEGO">Riego</option>
                      <option value="SECANO">Secano</option>
                    </select>
                  </div>
                </div>

                {/* Captura de GPS Nativo en Edición */}
                <div className="pt-2">
                  <button
                    type="button"
                    onClick={() => capturarGPS(true)}
                    className="w-full py-3 bg-emerald-50 hover:bg-emerald-100 text-emerald-800 border border-emerald-200 hover:border-emerald-300 rounded-2xl text-xs font-bold transition-all flex items-center justify-center gap-2 shadow-sm"
                  >
                    <Compass className={`w-4.5 h-4.5 text-emerald-600 ${gpsLoadingEdit ? 'animate-spin' : ''}`} />
                    {gpsLoadingEdit ? 'Accediendo a satélites GPS...' : 'Actualizar Coordenadas GPS del Teléfono'}
                  </button>
                </div>

                <div className="grid grid-cols-2 gap-4">
                  <div>
                    <label className="block text-2xs font-extrabold text-gray-500 uppercase tracking-wider mb-1">Latitud GPS</label>
                    <input 
                      type="number" step="0.000001"
                      value={editingLote.latitud}
                      onChange={(e) => setEditingLote({...editingLote, latitud: e.target.value})}
                      className="w-full px-4 py-3 bg-[#F8FAF9] border border-gray-200 rounded-xl focus:ring-2 focus:ring-emerald-500 outline-none transition-all font-semibold text-gray-900"
                    />
                  </div>
                  <div>
                    <label className="block text-2xs font-extrabold text-gray-500 uppercase tracking-wider mb-1">Longitud GPS</label>
                    <input 
                      type="number" step="0.000001"
                      value={editingLote.longitud}
                      onChange={(e) => setEditingLote({...editingLote, longitud: e.target.value})}
                      className="w-full px-4 py-3 bg-[#F8FAF9] border border-gray-200 rounded-xl focus:ring-2 focus:ring-emerald-500 outline-none transition-all font-semibold text-gray-900"
                    />
                  </div>
                </div>

                <div className="mt-8 flex gap-3 pt-4 border-t border-emerald-50">
                  <button 
                    type="button" 
                    onClick={() => setIsEditModalOpen(false)}
                    className="flex-1 px-4 py-3 text-gray-600 font-bold bg-[#F8FAF9] border border-gray-200 hover:bg-gray-100 rounded-xl transition-all"
                  >
                    Cancelar
                  </button>
                  <button 
                    type="submit" 
                    disabled={saving}
                    className="flex-1 px-4 py-3 text-white font-bold bg-gradient-to-r from-emerald-600 to-[#4C9A2A] hover:from-emerald-500 hover:to-emerald-400 rounded-xl shadow-md transition-all flex justify-center items-center gap-2"
                  >
                    {saving ? <><Loader className="w-5 h-5 animate-spin" /> Guardando</> : 'Guardar Cambios'}
                  </button>
                </div>
              </form>
            </motion.div>
          </div>
        )}
      </AnimatePresence>
    </div>
  );
}
